using System;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.StudentLife;using Rootborn.UI.StudentLife;
namespace Rootborn.Tests.EditMode.UI{public sealed class CareerPanelPolishTests{
[TestCase("ko","진로 후보","닫기")][TestCase("en","Career Candidates","Close")]
public void CandidatePanelLocalizesChromeAndBlocksWorldUntilClosed(string language,string title,string close){string old=GameText.Language;var go=new GameObject("CandidateModalFixture",typeof(RectTransform),typeof(Canvas));CareerCandidatePanel p=null;try{GameText.Language=language;p=CareerCandidatePanel.EnsureInScene(go.GetComponent<Canvas>());p.Show(Array.Empty<CareerCandidateDefinition>(),null,null);var texts=go.GetComponentsInChildren<Text>(true);Assert.That(texts.First(x=>x.name=="Title").text,Is.EqualTo(title));Assert.That(go.GetComponentsInChildren<Button>(true).First(x=>x.name=="CloseButton").GetComponentInChildren<Text>().text,Is.EqualTo(close));Assert.That(UiGameplayInputLock.IsBlocked,Is.True);Assert.That(go.GetComponentsInChildren<ScrollRect>(true).Any(s=>s.vertical),Is.True);p.Hide();Assert.That(UiGameplayInputLock.IsBlocked,Is.False);}finally{if(p!=null)UiGameplayInputLock.Release(p);UnityEngine.Object.DestroyImmediate(go);GameText.Language=old;}}
[Test]public void CandidateScrollViewportStaysInsidePanel(){var go=new GameObject("CandidateBoundsFixture",typeof(RectTransform),typeof(Canvas));try{var p=CareerCandidatePanel.EnsureInScene(go.GetComponent<Canvas>());p.Show(Array.Empty<CareerCandidateDefinition>(),null,null);var root=go.GetComponentsInChildren<RectTransform>(true).First(x=>x.name=="CareerCandidateRoot");var r=go.GetComponentsInChildren<ScrollRect>(true).First(x=>x.name=="CandidateListViewport").viewport;Assert.That(r.anchoredPosition.y-r.sizeDelta.y/2,Is.GreaterThanOrEqualTo(-root.sizeDelta.y/2+32));Assert.That(r.anchoredPosition.y+r.sizeDelta.y/2,Is.LessThanOrEqualTo(root.sizeDelta.y/2-32));Assert.That(r.anchoredPosition.x-r.sizeDelta.x/2,Is.GreaterThanOrEqualTo(-root.sizeDelta.x/2+32));}finally{UnityEngine.Object.DestroyImmediate(go);}}
[Test]public void EightCandidatesRemainReachableAndLongDetailsUseScrollableContent(){var go=new GameObject("CandidateEightFixture",typeof(RectTransform),typeof(Canvas));var definitions=new CareerCandidateDefinition[8];try{for(int i=0;i<8;i++){definitions[i]=ScriptableObject.CreateInstance<CareerCandidateDefinition>();var actions=Enumerable.Range(0,40).Select(n=>"추천 활동 "+i+" / "+n).ToArray();definitions[i].ConfigureForTests("candidate."+i,"진로 "+i,"설명 "+i,null,null,actions,null,null);}var p=CareerCandidatePanel.EnsureInScene(go.GetComponent<Canvas>());p.Show(definitions,new CareerCandidateProgress("slot","player"),new StudentLifeProgress("slot","player",10,10));var buttons=go.GetComponentsInChildren<Button>(true).Where(b=>b.name.StartsWith("CandidateButton_")).ToArray();Assert.That(buttons.Length,Is.GreaterThanOrEqualTo(8),"All eight authored candidate routes must be reachable");var list=go.GetComponentsInChildren<ScrollRect>(true).First(x=>x.name=="CandidateListViewport");Assert.That(list.content.rect.height,Is.GreaterThan(list.viewport.rect.height));buttons.First(b=>b.name=="CandidateButton_7").onClick.Invoke();var details=go.GetComponentsInChildren<ScrollRect>(true).First(x=>x.name=="CandidateDetailsViewport");Assert.That(details.content.rect.height,Is.GreaterThan(details.viewport.rect.height));Assert.That(details.content.GetComponent<Text>().text,Does.Contain("추천 활동 7 / 39"));}finally{UnityEngine.Object.DestroyImmediate(go);foreach(var d in definitions)if(d!=null)UnityEngine.Object.DestroyImmediate(d);}}
[Test]public void InterestPanelDistinguishesSelectedFromEligibleAndOwnsModalLock(){string old=GameText.Language;GameText.Language="ko";var go=new GameObject("InterestModalFixture",typeof(RectTransform),typeof(Canvas));var a=ScriptableObject.CreateInstance<CareerInterestDefinition>();var b=ScriptableObject.CreateInstance<CareerInterestDefinition>();CareerInterestPanel p=null;try{a.ConfigureForTests("a","관심 A","설명 A",null,null,null,null,null,null,null);b.ConfigureForTests("b","관심 B","설명 B",null,null,null,null,null,null,null);var progress=CareerInterestProgress.FromSaveData(new CareerInterestProgressSaveData{SaveSlot="slot",PlayerId="player",CurrentInterestId="a"});p=CareerInterestPanel.EnsureInScene(go.GetComponent<Canvas>());p.Show(new[]{a,b},progress,null,null,1);Assert.That(UiGameplayInputLock.IsBlocked,Is.True);string first=p.GetInterestButtonForTests(0).GetComponentInChildren<Text>().text,second=p.GetInterestButtonForTests(1).GetComponentInChildren<Text>().text;Assert.That(first,Does.Contain("선택됨"));Assert.That(second,Does.Contain("선택 가능"));Assert.That(go.GetComponentsInChildren<Text>(true).Any(x=>x.text.Contains("Selected")),Is.False);p.Hide();Assert.That(UiGameplayInputLock.IsBlocked,Is.False);}finally{if(p!=null)UiGameplayInputLock.Release(p);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);GameText.Language=old;}}
}}

